messages.content:
Tool response:
Tool: add_ingredient
Description: Add Ingredient
Parameters:
    {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "title": "Name"
        },
        "category": {
          "type": "string",
          "enum": [
            "hops",
            "malt",
            "yeast",
            "adjunct",
            "other"
          ],
          "title": "Category"
        },
        "alpha_acid": {
          "anyOf": [
            {
              "type": "number"
            },
            {
              "type": "null"
            }
          ],
          "title": "Alpha Acid"
        },
        "purchase_date": {
          "type": "string",
          "title": "Purchase Date"
        },
        "expiration_date": {
          "type": "string",
          "title": "Expiration Date"
        },
        "cost": {
          "type": "number",
          "title": "Cost"
        },
        "quantity": {
          "type": "number",
          "title": "Quantity"
        },
        "unit": {
          "type": "string",
          "enum": [
            "kg",
            "g",
            "lb",
            "oz",
            "L",
            "mL",
            "gal"
          ],
          "title": "Unit"
        }
      },
      "required": [
        "name",
        "category",
        "purchase_date",
        "expiration_date",
        "cost",
        "quantity",
        "unit"
      ]
    }
